public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();
    if (nums.length == 0) {
        return permutations;
    }

    recursivePermute(nums, 0, new ArrayList<>(), permutations);
    return permutations;
}

private void recursivePermute(int[] nums, int start, ArrayList<Integer> prefix, List<List<Integer>> permutations) {
    if (start == nums.length) {
        permutations.add(new ArrayList<>(prefix));
        return;
    }

    for (int i = start; i < nums.length; i++) {
        prefix.add(nums[i]);
        recursivePermute(nums, i + 1, prefix, permutations);
        prefix.remove(prefix.size() - 1);
    }
}

static List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    _permute(nums, 0, result);
    return result;
}

private static void _permute(int[] nums, int start, List<List<Integer>> result) {
    if (start == nums.length) {
        result.add(Arrays.asList(nums.clone()));
    } else {
        for (int i = start; i < nums.length; i++) {
            swap(nums, start, i);
            _permute(nums, start + 1, result);
            swap(nums, start, i);
        }
    }
}

private static void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 1) {
        result.add(Arrays.asList(nums));
    } else {
        for (int i = 0; i < nums.length; i++) {
            int[] left = Arrays.copyOfRange(nums, 0, i);
            int[] right = Arrays.copyOfRange(nums, i + 1, nums.length);
            List<List<Integer>> leftPermute = permute(left);
            for (List<Integer> list : leftPermute) {
                List<Integer> newList = new ArrayList<>();
                newList.add(nums[i]);
                newList.addAll(list);
                result.add(newList);
            }
            List<List<Integer>> rightPermute = permute(right);
            for (List<Integer> list : rightPermute) {
                List<Integer> newList = new ArrayList<>();
                newList.addAll(list);
                newList.add(nums[i]);
                result.add(newList);
            }
        }
    }
    return result;
}

