public static int findLargestSubstring(List<String> strings) {
    // Find the longest substring that can be found as a prefix or suffix of any of the given strings
    int longestSubstring = 0;
    for (int i = 0; i < strings.size(); i++) {
        int currentLength = strings.get(i).length();
        for (int j = 0; j < currentLength; j++) {
            String substring = strings.get(i).substring(j);
            if (strings.stream().filter(s -> s.contains(substring)).count() > 0) {
                longestSubstring = Math.max(longestSubstring, substring.length());
            }
            if (strings.stream().filter(s -> s.contains(substring.reverse())).count() > 0) {
                longestSubstring = Math.max(longestSubstring, substring.length());
            }
        }
    }
    return longestSubstring;
}

