public int findLargestSubstring(List<String> strings) {
    // Initialize the largest substring length to 0
    int largestSubstringLength = 0;

    // Loop over the given strings and check for substrings
    for (String string : strings) {
        // Check for the substring in the string and its inverse
        for (int i = 0; i < string.length(); i++) {
            String substring = string.substring(i);
            String inverse = new StringBuilder(substring).reverse().toString();
            // Update the largest substring length if the substring or its inverse is found
            if (largestSubstringLength < substring.length() ||
                largestSubstringLength < inverse.length()) {
                largestSubstringLength = Math.max(substring.length(),
                                                   inverse.length());
            }
        }
    }

    // Return the largest substring length
    return largestSubstringLength;
}

