public static int maxRegions(int N) {
    int regions = 0;

    // Base case: If N is 1, there are 2 regions
    if (N == 1) {
        return 2;
    }

    // Recursive case: Divide the plane into 2 parts and calculate the maximum number of regions in each part
    int part1 = maxRegions(N / 2);
    int part2 = maxRegions(N - N / 2);

    // Return the maximum of the 2 parts
    return Math.max(part1, part2);
}

public static int maxRegions(int N) {
        // Base case: 2 regions for 0 or 1 triangle
        if (N <= 1) {
            return 2;
        }

        // Recursive case: divide and conquer
        int currRegion = 0;
        for (int i = 1; i < N; i++) {
            // Triangle formed by 1st triangle and current triangle
            int triangle1 = i;
            int triangle2 = N - i;
            int region1 = maxRegions(triangle1) * maxRegions(triangle2);

            // Triangle formed by current triangle and last triangle
            triangle1 = i;
            triangle2 = N - i - 1;
            int region2 = maxRegions(triangle1) * maxRegions(triangle2);

            // Update current region
            currRegion = Math.max(currRegion, region1, region2);
        }

        return currRegion;
    }

