public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {

if (n < 2) {
return "cannot be travelled";
}

LinkedList<Integer> stack = new LinkedList<Integer>();
int[][] visited = new int[n][n];

stack.push(start[0]);
stack.push(start[1]);
visited[start[0]][start[1]] = 1;

while (!stack.isEmpty()) {
int x = stack.pop();
int y = stack.pop();

if (x == end[0] && y == end[1]) {
return "can be travelled";
}

for (int[] path : paths) {
if (path[0] == x && path[1] == y) {
stack.push(path[2]);
stack.push(path[3]);
visited[path[2]][path[3]] = 1;
}
}
}

return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize the graph with the given paths
    Graph<int[]> mazeGraph = new Graph<>();
    for (int[] path : paths) {
        mazeGraph.addEdge(path[0], path[1], path);
    }

    // Perform Breadth-First Search on the graph to check if there is a path from the starting to the ending n-tersection
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    Set<int[]> visited = new HashSet<>();
    while (!queue.isEmpty()) {
        int[] currentPos = queue.poll();
        if (currentPos[0] == end[0] && currentPos[1] == end[1]) {
            return "can be travelled";
        }
        for (int[] neighbor : mazeGraph.adjacencies(currentPos)) {
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths)
  {
    // Initialize the set of visited n-tersections
    Set<Integer> visited = new HashSet<>();
    // Initialize the queue for BFS
    Queue<Integer> queue = new ArrayDeque<>();
    // Add the starting n-tersection to the queue
    queue.add(start[0]);
    // Initialize the hashmap to store the parent of each n-tersection
    Map<Integer, Integer> parent = new HashMap<>();
    // Loop until the queue is empty
    while (!queue.isEmpty())
    {
      // Get the next n-tersection from the queue
      int current = queue.poll();
      // If the current n-tersection is the ending n-tersection, we have found a possible path
      if (current == end[0]) return "can be travelled";
      // If the current n-tersection has not been visited, mark it as visited
      // and add its neighbors to the queue and hashmap
      if (!visited.contains(current))
      {
        visited.add(current);
        for (int[] path : paths)
        {
          if (current == path[0])
          {
            queue.add(path[1]);
            parent.put(path[1], current);
          }
        }
      }
    }
    // If the current n-tersection is not the ending n-tersection, we cannot travel
    return "cannot be travelled";
  }

public static String appx(String word1, String word2) {
    Objects.requireNonNull(word1, "word1 cannot be null");
    Objects.requireNonNull(word2, "word2 cannot be null");

    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }

    int word1Length = word1.length();
    int word2Length = word2.length();
    int gcd = greatestCommonDenominator(word1Length, word2Length);
    int numerator = commonLetters * gcd;
    int denominator = word1Length * word2Length;

    return String.format("appx(%s, %s) = %d/%d", word1, word2, numerator, denominator);
}

private static int greatestCommonDenominator(int a, int b) {
    if (b == 0) {
        return a;
    }
    return greatestCommonDenominator(b, a % b);
}

public static String appx(String word1, String word2) {
