        for (int j = 0; j < len2; j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                count++;
                break;
            }
        }
    }

    int approx = count * 100 / (len1 + len2);
    int gcd = gcd(approx, 100);

    return String.format("%d/%d", approx / gcd, 100 / gcd);
}

