public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Remove the smallest 5% of elements
    int min = (int) (arr.length * 0.05);
    int[] subArr = Arrays.copyOfRange(arr, min, arr.length - min);

    // Remove the largest 5% of elements
    int max = (int) (subArr.length * 0.05);
    int[] subSubArr = Arrays.copyOfRange(subArr, max, subArr.length - max);

    // Calculate the mean of the remaining elements
    double mean = subSubArr.stream().mapToDouble(i -> i).average().getAsDouble();

    return mean;
}

public double trimMean(int[] arr) {
    // Calculate the 5% smallest elements
    PriorityQueue<Integer> minHeap = new PriorityQueue<>(
        Comparator.comparingInt(a -> -a));
    for (int i = 0; i < 5*arr.length/100; i++) {
        minHeap.add(arr[i]);
    }
    int[] smallestElements = new int[5*arr.length/100];
    for (int i = 0; i < 5*arr.length/100; i++) {
        smallestElements[i] = minHeap.poll();
    }

    // Calculate the 5% largest elements
    PriorityQueue<Integer> maxHeap = new PriorityQueue<>(
        Comparator.comparingInt(a -> a));
    for (int i = 0; i < 5*arr.length/100; i++) {
        maxHeap.add(arr[arr.length - i - 1]);
    }
    int[] largestElements = new int[5*arr.length/100];
    for (int i = 0; i < 5*arr.length/100; i++) {
        largestElements[i] = maxHeap.poll();
    }

    // Calculate the mean of the remaining elements
    int sum = 0;
    for (int i = 5*arr.length/100; i < arr.length - 5*arr.length/100; i++) {
        sum += arr[i];
    }
    return (sum + 0.0) / (arr.length - 2*5*arr.length/100);
}

public double trimMean(int[] arr) {
    int threshold = (int) (arr.length * 0.05);
    int start = threshold, end = arr.length - threshold - 1;
    int sum = 0;
    for (int i = start; i <= end; i++) {
        sum += arr[i];
    }
    return (double) sum / (arr.length - 2 * threshold);
}

public double trimMean(int[] arr) {
  	// Find the smallest 5% of elements
	int smallest = (int)(arr.length * 0.05);
	quicksort(arr, 0, arr.length - 1, smallest);

	// Find the largest 5% of elements
	int largest = (int)(arr.length * 0.05);
	quicksort(arr, 0, arr.length - 1, arr.length - largest);

	// Calculate the mean of the remaining elements
	int sum = 0;
	for (int i = smallest; i < arr.length - largest; i++) {
		sum += arr[i];
	}
	return (double)sum / (arr.length - 2 * smallest);
}

private void quicksort(int[] arr, int left, int right, int index) {
	if (left >= right)
		return;
	int pivot = arr[index];
	int i = left;
	int j = right;
	while (i <= j) {
		while (arr[i] < pivot)
			i++;
		while (arr[j] > pivot)
			j--;
		if (i <= j) {
			swap(arr, i, j);
			i++;
			j--;
		}
	}
	quicksort(arr, left, j, index);
	quicksort(arr, i, right, index);
}

private void swap(int[] arr, int i, int j) {
	int temp = arr[i];
	arr[i] = arr[j];
	arr[j] = temp;
}

public static boolean canArrange(int[] arr, int k) {
  Set<Integer> set = new HashSet<>();
  for (int number : arr) {
   if (number % k == 0) {
    set.add(number);
   }
  }
  int n = set.size();
  if (n % 2 != 0) {
   return false;
  }
  int pairs = n / 2;
  int sum = 0;
  for (int i = 0; i < pairs; i++) {
   int number1 = set.iterator().next();
   set.remove(number1);
   int number2 = set.iterator().next();
   set.remove(number2);
   sum += number1 + number2;
  }
  return sum % k == 0;
 }

