        sum += arr[i];
    }
    if (sum % k != 0) {
        return false;
    }
    int n = arr.length;
    int m = sum / k;
    if (m % 2 != 0) {
        return false;
    }
    int[] pairs = new int[m];
    Arrays.fill(pairs, 0);
    for (int i = 0; i < n; i++) {
        pairs[i % m] += arr[i];
    }
    for (int i = 0; i < m; i++) {
        if (pairs[i] % k != 0) {
            return false;
        }
    }
    return true;
}

