    int n = arr.length;
    int[] pairs = new int[n/2];

    // Iterate through the array, pairing adjacent elements
    for (int i = 0; i < n; i += 2) {
        pairs[i/2] = arr[i] + arr[i + 1];
    }

    // Check if the sums of the pairs are divisible by k
    for (int sum : pairs) {
        if (sum % k != 0) {
            return false;
        }
    }

    // If the sums of the pairs are all divisible by k, return true
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Initialize a graph with n nodes
  Graph graph = new Graph(n);
  for (int[] edge : edges) {
    graph.addEdge(edge[0], edge[1]);
  }

  // Initialize a distance array to store the minimum distance needed to reach each node
  int[] distance = new int[n];
  Arrays.fill(distance, Integer.MAX_VALUE);
  distance[0] = 0;

  // Use BFS to find the minimum distance from node 0 to all other nodes
  Queue<Integer> queue = new ArrayDeque<>();
  queue.offer(0);
  while (!queue.isEmpty()) {
    int node = queue.poll();
    for (int neighbor : graph.adjacencyList.get(node)) {
      if (hasApple[neighbor] && distance[neighbor] > distance[node] + 1) {
        distance[neighbor] = distance[node] + 1;
        queue.offer(neighbor);
      }
    }
  }

  // Return the minimum distance from node 0 to all other nodes
  return distance[0] + distance[1];
}

