public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a queue to store the nodes to visit
    Queue<Integer> queue = new LinkedList<>();
    // Initialize a boolean array to mark the visited nodes
    boolean[] visited = new boolean[n];
    // Initialize the time counter
    int time = 0;

    // Enqueue the starting node and mark it as visited
    queue.offer(0);
    visited[0] = true;

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the size of the current level
        int levelSize = queue.size();
        // Loop through the nodes in the current level
        for (int i = 0; i < levelSize; i++) {
            // Get the current node
            int node = queue.poll();
            // If the node has an apple and it's not the starting node
            if (hasApple[node] && node != 0) {
                // Add the apple to the time counter
                time++;
                // If the node has an apple and it's not the starting node
                if (node == n - 1) {
                    // If we have collected all the apples, return the time
                    return time;
                }
            }
            // Get the neighbors of the current node
            for (int neighbor : edges[node]) {
                // If the neighbor has not been visited
                if (!visited[neighbor]) {
                    // Mark the neighbor as visited
                    visited[neighbor] = true;
                    // Enqueue the neighbor
                    queue.offer(neighbor);
                }
            }
        }
        // Increment the time counter
        time++;
    }
    // If we have not collected all the apples, return -1
    return -1;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (hasApple[0]) {
        return 0;
    }
    int[] dist = new int[n];
    for (int i = 0; i < n; i++) {
        dist[i] = Integer.MAX_VALUE;
    }
    dist[0] = 0;
    boolean[] visited = new boolean[n];
    PriorityQueue<Integer> pq = new PriorityQueue<>();
    pq.offer(0);
    while (!pq.isEmpty()) {
        int node = pq.poll();
        if (visited[node]) {
            continue;
        }
        visited[node] = true;
        for (int i = 0; i < edges[node].length; i++) {
            int neighbor = edges[node][i];
            if (hasApple[neighbor]) {
                if (dist[neighbor] > dist[node] + 1) {
                    dist[neighbor] = dist[node] + 1;
                    pq.offer(neighbor);
                }
            }
        }
    }
    return dist[n - 1];
}

