public String sortString(String s) {
    String result = "";
    while (!s.isEmpty()) {
        char smallest = s.charAt(0);
        int smallestIndex = 0;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) < smallest) {
                smallest = s.charAt(i);
                smallestIndex = i;
            }
        }
        result += smallest;
        s = s.substring(smallestIndex) + s.substring(0, smallestIndex);
        if (s.isEmpty()) {
            break;
        }
        char largest = s.charAt(s.length() - 1);
        int largestIndex = s.length() - 1;
        for (int i = s.length() - 2; i >= 0; i--) {
            if (s.charAt(i) > largest) {
                largest = s.charAt(i);
                largestIndex = i;
            }
        }
        result += largest;
        s = s.substring(largestIndex) + s.substring(0, largestIndex);
    }
    return result;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    char[] array = s.toCharArray();
    Arrays.sort(array);
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < array.length; i++) {
        char c = array[i];
        if (i % 2 == 0) {
            sb.append(c);
        } else {
            for (int j = array.length - 1; j > i; j--) {
                if (array[j] > c) {
                    sb.append(array[j]);
                    break;
                }
            }
        }
    }
    for (int i = array.length - 1; i >= 0; i--) {
        char c = array[i];
        if (i % 2 == 1) {
            sb.append(c);
        } else {
            for (int j = 0; j < i; j++) {
                if (array[j] < c) {
                    sb.append(array[j]);
                    break;
                }
            }
        }
    }
    return sb.toString();
}

