    // Calculate the average of the input array
    double average = (double)sum / nums.length;

    // Initialize two variables to keep track of the sum of the left and right arrays
    int leftSum = 0;
    int rightSum = 0;

    // Iterate over the input array
    for (int i = 0; i < nums.length; i++) {
        // Add the current element to the left or right sum
        if (i < nums.length / 2) {
            leftSum += nums[i];
        } else {
            rightSum += nums[i];
        }

        // Check if the average is equal to the sum of the left and right arrays
        if (leftSum == rightSum && leftSum == average) {
            return true;
        }
    }

    return false;
}

