public boolean splitArraySameAverage(int[] nums) {
    // Calculate the average of the entire array
    int average = Arrays.stream(nums).sum() / nums.length;

    // Initialize two variables to keep track of the sum of the left and right subarrays
    int leftSum = 0, rightSum = 0;
    // Initialize two variables to keep track of the length of the left and right subarrays
    int leftLength = 0, rightLength = 0;

    // Iterate through the array
    for (int i = 0; i < nums.length; i++) {
        // If the current element is less than the average, add it to the left subarray
        if (nums[i] < average) {
            leftSum += nums[i];
            leftLength++;
        // Otherwise, add it to the right subarray
        } else {
            rightSum += nums[i];
            rightLength++;
        }
    }

    // Check if the sum of the left and right subarrays is equal to the average
    return leftSum == rightSum && leftLength == rightLength;
}

public boolean splitArraySameAverage(int[] nums) {
    // Check if the array is empty
    if (nums.length == 0) {
        return false;
    }

    // Calculate the average of the array
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int average = sum / nums.length;

    // Check if the array has an even number of elements
    if (nums.length % 2 == 0) {
        // Check if the average is an integer
        if (average % 1 == 0) {
            // Split the array in half
            int[] left = Arrays.copyOfRange(nums, 0, nums.length / 2);
            int[] right = Arrays.copyOfRange(nums, nums.length / 2, nums.length);

            // Check if the averages of the two halves are equal
            if (average == (left.length > 0 ? left[left.length - 1] : 0) + (right.length > 0 ? right[0] : 0)) {
                return true;
            }
        }
    } else {
        // Find the median of the array
        int median = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] > median) {
                median = nums[i];
            }
        }

        // Check if the median is an integer
        if (median % 1 == 0) {
            // Split the array around the median
            int[] left = Arrays.copyOfRange(nums, 0, median);
            int[] right = Arrays.copyOfRange(nums, median, nums.length);

            // Check if the averages of the two halves are equal
            if (average == (left.length > 0 ? left[left.length - 1] : 0) + (right.length > 0 ? right[0] : 0)) {
                return true;
            }
        }
    }

    // If we reach this point, it is not possible to split the array
    return false;
}

