public int minCostClimbingStairs(int[] cost) {
  int totalCost = 0;
  for (int i = 2; i < cost.length; i++) {
    int step1Cost = cost[i - 1] + cost[i - 2];
    int step2Cost = cost[i] + cost[i - 1];
    totalCost = Math.min(step1Cost, step2Cost);
  }
  return totalCost;
}

public int minCostClimbingStairs(int[] cost) {
  int minCost = 0;
  int secondMinCost = 0;

  for (int i = 0; i < cost.length - 1; i++) {
    int currentCost = cost[i] + Math.min(minCost, secondMinCost);
    secondMinCost = minCost;
    minCost = currentCost;
  }

  return Math.min(minCost, secondMinCost);
}

