public boolean hasAllCodes(String s, int k) {
    int len = s.length();
    int count = 0;
    for (int i = 0; i < len; i++) {
        String substr = s.substring(i, i + k);
        if (substr.matches("^[01]{k}$")) {
            count++;
        }
    }
    return count == (1 << k);
}

public boolean hasAllCodes(String s, int k) {
  // Check if the input string is null or empty
  if (s == null || s.length() == 0) {
    return false;
  }

  // Check if the substring length is valid
  if (k < 1 || k > s.length()) {
    return false;
  }

  // Initialize a set to store all substrings of length k
  Set<String> substrings = new HashSet<>();

  // Iterate over the input string
  for (int i = 0; i < s.length() - k + 1; i++) {
    // Extract the current substring of length k
    String substring = s.substring(i, i + k);

    // Check if the substring is already present in the set
    if (!substrings.contains(substring)) {
      // If the substring is not present, add it to the set
      substrings.add(substring);
    } else {
      // If the substring is already present, return false
      return false;
    }
  }

  // If all substrings are present, return true
  return true;
}

