public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int operations = 0;
    while (operations < n) {
        int x = 0;
        int y = 0;
        for (int i = 0; i < n; i++) {
            if (arr[i] != arr[0]) {
                x = i;
                y = 0;
                break;
            }
        }

        arr[x] -= 1;
        arr[y] += 1;
        operations++;
    }

    return operations;
}

public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int operations = 0;
    while (!isArrayEqual(arr)) {
        int[] minElement = findMinElement(arr);
        int[] maxElement = findMaxElement(arr);
        arr[minElement[0]]--;
        arr[maxElement[0]]++;
        operations++;
    }
    return operations;
}

private boolean isArrayEqual(int[] arr) {
    int minElement = findMinElement(arr);
    int maxElement = findMaxElement(arr);
    return maxElement - minElement <= 1;
}

private int[] findMinElement(int[] arr) {
    int minElement = 0;
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] < arr[minElement]) {
            minElement = i;
        }
    }
    return new int[]{minElement, arr[minElement]};
}

private int[] findMaxElement(int[] arr) {
    int maxElement = 0;
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] > arr[maxElement]) {
            maxElement = i;
        }
    }
    return new int[]{maxElement, arr[maxElement]};
}

public int minOperations(int n) {
  // Initialize the result variable
  int result = 0;

  // Loop through the array
  for (int i = 1; i < n; i++) {
    // Calculate the distance between the current element and the element at index 0
    int distance = Math.abs(arr[i] - arr[0]);

    // If the distance is greater than 1
    if (distance > 1) {
      // Add the number of operations required to make the distance equal to 1
      result += distance - 1;
    }

    // Subtract the current element from the sum
    result -= arr[i];

    // Add the current element to the sum
    result += arr[i];
  }

  // Return the result
  return result;
}

