    // Add the value of the current element to the current sum
    currSum += (2 * i) + 1;
    // If the current sum is greater than or equal to n, we need to perform one fewer operation
    if (currSum >= n) {
      minOps++;
      // Subtract the value of the current element from the current sum
      currSum -= (2 * i) + 1;
    }
  }
  return minOps;
}

