public static int findMinFibonacciNumbers(int k) {
    // Initialize the minimum number of Fibonacci numbers to 1 if the sum is 1
    int minFibonacciNumbers = 1;
    int previousFibonacciNumber = 1;
    int currentFibonacciNumber = 1;

    // Loop until the sum of Fibonacci numbers is greater than or equal to k
    while (currentFibonacciNumber < k) {
        // Add the current Fibonacci number to the sum of Fibonacci numbers
        minFibonacciNumbers++;
        int temp = previousFibonacciNumber;
        previousFibonacciNumber = currentFibonacciNumber;
        currentFibonacciNumber = temp + currentFibonacciNumber;
    }

    // If the sum of Fibonacci numbers is equal to k, return the minimum number of Fibonacci numbers
    if (currentFibonacciNumber == k) {
        minFibonacciNumbers--;
    }

    return minFibonacciNumbers;
}

public int findMinFibonacciNumbers(int k) {
    // Edge case: k = 0
    if (k == 0) {
        return 0;
    }

    // Initialize Fibonacci sequence up to the greatest Fibonacci number that is less than or equal to k
    int[] fib = new int[k + 1];
    fib[0] = 0;
    fib[1] = 1;
    for (int i = 2; i <= k; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }

    // Find the right Fibonacci number that is closest to k
    int right = 0;
    for (int i = k; i >= 0; i--) {
        if (fib[i] <= k) {
            right = i;
            break;
        }
    }

    // Find the left Fibonacci number that is closest to k
    int left = 0;
    for (int i = k; i >= 0; i--) {
        if (fib[i] <= k) {
            left = i;
            break;
        }
    }

    // Return the minimum number of Fibonacci numbers that sum to k
    return right - left + 1;
}

