    fibonacci[i] = fibonacci[i - 1] + fibonacci[i - 2];
  }

  int count = 0;
  for (int i = 0; i < k; i++) {
    if (fibonacci[i] <= k) {
      count++;
      k -= fibonacci[i];
    }
  }

  return count;
}

