public int maxUniqueSplit(String s) {
    Set<String> uniqueSubstrings = new HashSet<>();
    int maxCount = 0;

    for (int i = 0; i < s.length(); i++) {
        String substring = s.substring(i);
        if (uniqueSubstrings.contains(substring)) {
            continue;
        }

        int count = 1;
        for (int j = 1; j < substring.length(); j++) {
            String subsubstring = substring.substring(0, j);
            if (uniqueSubstrings.contains(subsubstring)) {
                count++;
            }
        }

        uniqueSubstrings.add(substring);
        maxCount = Math.max(maxCount, count);
    }

    return maxCount;
}

public int maxUniqueSplit(String s) {
    // Initialize the result variable
    int result = 0;

    // Loop through each character in the string
    for (int i = 0; i < s.length(); i++) {
        // Create a set to store the unique substrings
        Set<String> set = new HashSet<>();

        // Loop through each character in the substring
        for (int j = i; j < s.length(); j++) {
            // Add the substring to the set
            set.add(s.substring(i, j + 1));
        }

        // Update the result if the set size is greater than the current result
        if (set.size() > result) {
            result = set.size();
        }
    }

    return result;
}

public static int maxUniqueSplit(String s) {
        if (s == null || s.length() < 1) {
            return 0;
        }
        // Store the indices of each character in the current substring.
        int[] indices = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            indices[i] = s.charAt(i) - 'a';
        }

        // Split the string into substrings of unique characters.
        List<String> substrings = new LinkedList<>();
        int[] seen = new int[26];
        int max = 0;
        for (int i = 0; i < s.length(); i++) {
            if (seen[indices[i]] == 0) {
                // If the current character has not been seen before, add it to
                // the current substring.
                String substring = s.substring(i);
                substrings.add(substring);
                seen[indices[i]] = 1;
                max++;
            } else {
                // If the current character has been seen before, remove it from
                // the current substring until a unique character is encountered.
                int index = i - 1;
                while (index >= 0 && seen[indices[index]] == 1) {
                    index--;
                }
                if (index < 0) {
                    // If we reach the beginning of the string without finding a
                    // unique character, remove the current character from the
                    // current substring.
                    substrings.remove(s.substring(i));
                    seen[indices[i]] = 0;
                    max--;
                } else {
                    int start = index + 1;
                    // Add the substring from the beginning to the current index.
                    substrings.add(s.substring(start, i + 1));
                    // Remove the substring from the beginning to the current index.
                    substrings.remove(s.substring(start, index + 1));
                    // Update the indices of the characters in the current substring.
                    for (int j = start; j <= i; j++) {
                        indices[j] = s.charAt(j) - 'a';
                    }
                    // Decrement the number of unique substrings.
                    max--;
                }
            }
        }

        return max;
    }

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    //Initializations
    sb = new StringBuilder();
    map = new HashMap<Character, Integer>();
    buffer = new StringBuffer();

    //For each character in the string
    for (int i = 0; i < s.length(); i++) {
        char curr = s.charAt(i);
        //If the character is not in the map, add it
        if (!map.containsKey(curr)) {
            map.put(curr, 1);
            sb.append(curr);
        }
        //If the character is in the map, increment its frequency
        else {
            int freq = map.get(curr) + 1;
            map.put(curr, freq);
            //If the frequency is greater than 1, remove the character from the string builder
            if (freq > 2) {
                sb.deleteCharAt(sb.indexOf(curr));
            }
        }

        //Add the string builder to the buffer
        buffer.append(sb);
    }

    //Return the number of unique substrings in the buffer
    return buffer.length();
}

