    for (String log : logs) {
        if (log.startsWith("../")) {
            if (folderStack.size() == 1) {
                // Negative operation
                operations++;
            } else {
                // Remove the last folder from the stack
                folderStack.pop();
            }
        } else if (log.startsWith("./")) {
            // No-operation
        } else {
            // Add the new folder to the stack
            folderStack.push(log);
        }
    }

    return operations;
}

