public int minOperations(String[] logs) {
    int minOps = 0, pathLen = 1; // Start with 1 directory deep
    for (String log : logs) {
        if (log.equals(".")) continue; // If the path is not relative, skip
        else if (log.equals("..")) { // If the path goes up, decrease the depth
            if (pathLen == 1) return minOps + 1;
            pathLen--;
        } else if (log.equals("/")) { // If the path points to the main directory, reset
            pathLen = 1;
        } else { // Otherwise, new directory is added, increase the depth
            pathLen++;
        }
        minOps = Math.min(minOps, pathLen + 1); // Keep track of the minimum depth
    }
    return minOps;
}

else if (log.equals("..")) { // If the path goes up, decrease the depth
            if (pathLen == 1) return minOps + 1;
            pathLen--;
        }

public int minOperations(String[] logs) {
    int minOperations = 0;
    Stack<String> folderStack = new Stack<>();
    folderStack.push("");

    for (String log : logs) {
        if (log.equals("../")) {
            if (folderStack.isEmpty()) {
                return -1;
            }
            folderStack.pop();
        } else {
            folderStack.push(log);
        }
    }

    return folderStack.size();
}

public int minOperations(String[] logs) {
    Deque<String> folderStack = new LinkedList<>();
    folderStack.push("/");
    for (String log : logs) {
        if (log.equals("../")) {
            folderStack.pop();
        } else if (!log.equals("./")) {
            folderStack.push(folderStack.peek() + log);
        }
    }
    return folderStack.size() - 1;
}

