public static int squarePermutations(int[] A) {
    Set<Integer> permutations = new HashSet<>();
    for (int i = 0; i < A.length; i++) {
        int sum = 0;
        for (int j = i - 1; j <= i + 1; j++) {
            if (j >= 0 && j < A.length) {
                sum += A[j];
            }
        }
        int sqrt = (int) Math.sqrt(sum);
        if (sum == sqrt * sqrt) {
            permutations.add(sum);
        }
    }
