    for (int i = 1; i < n; i++) {
        left[i] = Math.max(left[i - 1], 0);
    }

    for (int i = n - 2; i >= 0; i--) {
        right[i] = Math.max(right[i + 1], 0);
    }

    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, (right[i] - left[i]) * heights[i]);
    }

    return maxArea;
}

