public static int largestRectangleArea(int[] heights) {
    // Edge case: No bars
    if (heights.length == 0) {
        return 0;
    }

    // Initialize variables
    int largestArea = 0;
    int currentArea = 0;
    int i = 0;
    int j = 0;

    // Loop through the bars
    while (i < heights.length) {
        // Calculate the width of the current bar
        j = i;
        while (j < heights.length && heights[j] == heights[i]) {
            j++;
        }

        // Calculate the area of the current bar
        currentArea = heights[i] * (j - i);

        // Update the largest area
        largestArea = Math.max(largestArea, currentArea);

        // Move on to the next bar
        i = j;
    }

    return largestArea;
}

