    }
}

private static int[] sortDigits(int n) {
    // Convert n to a string
    String nStr = String.valueOf(n);

    // Initialize an array to store the sorted digits
    int[] sortedDigits = new int[nStr.length()];

    // Sort the digits of n in ascending order
    for (int i = 0; i < nStr.length(); i++) {
        sortedDigits[i] = nStr.charAt(i) - '0';
    }
    Arrays.sort(sortedDigits);

    return sortedDigits;
}

private static int rearrangeDigits(int[] sortedDigits) {
    // Initialize a string to store the rearranged digits
    String rearrangedDigits = "";

    // Rearrange the sorted digits
    for (int i = 0; i < sortedDigits.length; i++) {
        rearrangedDigits += sortedDigits[i];
    }

    // Convert the rearranged digits to an integer
    return Integer.parseInt(rearrangedDigits);
}

