  int num = n;
  while (num > 0) {
    int digit = num % 10;
    digits[digit]++;
    num /= 10;
  }
  int smallest = -1;
  for (int i = 0; i < 10; i++) {
    if (digits[i] > 0) {
      smallest = i;
      break;
    }
  }
  if (smallest == -1) {
    return -1;
  }
  num = n;
  while (num > 0) {
    int digit = num % 10;
    if (digit == smallest) {
      num /= 10;
    } else {
      num -= digits[digit];
    }
  }
  return smallest * 10 + num;
}

