        return false;
    }

    // Check if any two points are equal
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                return false;
            }
        }
    }

    // Check if the three points are ordered clockwise
    int sum = 0;
    for (int i = 0; i < n; i++) {
        int x1 = points[i][0];
        int y1 = points[i][1];
        int x2 = points[i == n - 1 ? 0 : i + 1][0];
        int y2 = points[i == n - 1 ? 0 : i + 1][1];
