public static int findNthUglyNumber(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("The index must be a non-negative integer.");
    }

    int[] dp = new int[n + 1];
    dp[0] = 1;

    int index2 = 0, index3 = 0, index5 = 0;

    for (int i = 1; i <= n; i++) {
        int next2 = 2 * dp[index2];
        int next3 = 3 * dp[index3];
        int next5 = 5 * dp[index5];

        int min = Math.min(next2, Math.min(next3, next5));

        dp[i] = min;

        if (min == next2) {
            index2++;
        }
        if (min == next3) {
            index3++;
        }
        if (min == next5) {
            index5++;
        }
    }

    return dp[n];
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The index must be a positive integer.");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int uglyNumberIndex = 1;

    while (uglyNumberIndex < n) {
        int nextUglyNumber = Math.min(Math.min(uglyNumbers[uglyNumberIndex] * 2, uglyNumbers[uglyNumberIndex] * 3), uglyNumbers[uglyNumberIndex] * 5);
        uglyNumbers[uglyNumberIndex] = nextUglyNumber;
        uglyNumberIndex++;
    }

    return uglyNumbers[n - 1];
}

public static int findNthUglyNumber(int n) {
    if (n == 1) {
        return 1;
    }
    int[] dp = new int[n];
    dp[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    for (int i = 1; i < n; i++) {
        int min = Math.min(Math.min(dp[i2] * 2, dp[i3] * 3), dp[i5] * 5);
        dp[i] = min;
        if (min == dp[i2] * 2) {
            i2++;
        }
        if (min == dp[i3] * 3) {
            i3++;
        }
        if (min == dp[i5] * 5) {
            i5++;
        }
    }
    return dp[n - 1];
}

