    if (n < 1) throw new IllegalArgumentException("The index must be a positive integer.");

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int i2 = 0, i3 = 0, i5 = 0;
    for (int i = 1; i < n; i++) {
        int nextUglyNumber = Math.min(
            Math.min(uglyNumbers[i2] * 2, uglyNumbers[i3] * 3),
            uglyNumbers[i5] * 5
        );
        if (nextUglyNumber == uglyNumbers[i2] * 2) i2++;
        if (nextUglyNumber == uglyNumbers[i3] * 3) i3++;
        if (nextUglyNumber == uglyNumbers[i5] * 5) i5++;
        uglyNumbers[i] = nextUglyNumber;
    }

    return uglyNumbers[n - 1];
}

