            return 0;
        }
        int max = 0, current = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == s.charAt(i + 1)) {
                current++;
            } else {
                if (current > max) {
                    max = current;
                }
                current = 0;
            }
        }
        if (current > max) {
            max = current;
        }
        return max;
    }

public static int calculateEnergy(String s) {
    if (s == null || s.length() < 1) {
        return 0;
    }
    String longestNonEmptySubstring = getLongestNonEmptySubstring(s);
    return longestNonEmptySubstring.length();
}

private static String getLongestNonEmptySubstring(String s) {
    int max = 0, start = 0, end = 0;
    for (int i = 0; i < s.length(); i++) {
        int j = i;
        while (j < s.length() && s.charAt(j) == s.charAt(i)) {
            j++;
        }
        int currentLength = j - i;
        if (currentLength > max) {
            max = currentLength;
            start = i;
            end = j - 1;
        }
    }
    return s.substring(start, end + 1);
}

public static int calculateEnergy(String s) {
    int max = 0, start = 0, end = 0;
    for (int center = 0; center < s.length(); center++) {
        int i = center, j = center + 1;
        int halfLen = 0;
        while (i >= 0 && j < s.length() && s.charAt(i) == s.charAt(j)) {
            halfLen++;
            i--;
            j++;
        }
        int currentLength = halfLen * 2;
        if (currentLength > max) {
            max = currentLength;
            start = center - halfLen + 1;
            end = center + halfLen;
        }
    }
    return end - start + 1;
}

public static int calculateEnergy(String s) {
    int longest = 0;
    for (int i = 0; i < s.length(); i++) {
        int current = 1;
        for (int j = i + 1; j < s.length(); j++) {
            if (s.charAt(j) != s.charAt(i)) {
                break;
            }
            current++;
        }
        longest = Math.max(longest, current);
    }
    return longest;
}

