    // loop through the range of perfect squares
    for (int i = 1; i * i <= n; i++) {
        // if the current square is less than or equal to the target, add it to the list
        if (i * i <= n) {
            perfectSquares.add(i * i);
        }
    }

    // sort the list in ascending order
    perfectSquares.sort(Comparator.naturalOrder());

    // initialize a variable to store the minimum number of perfect square numbers
    int minSquares = 0;

    // loop through the list of perfect square numbers
    for (int square : perfectSquares) {
        // if the sum of the current square and the total is less than or equal to the target, increment the minimum number of perfect square numbers
        if (square + minSquares <= n) {
            minSquares++;
        }
    }

    // return the minimum number of perfect square numbers
    return minSquares;
}

